import Database from 'better-sqlite3';
import {writeFileSync} from 'node:fs';
import {createScriptRepository} from '../../apps/api/src/repositories/scriptStore';
import {createScriptProject,newUnit,newScene} from '../../packages/script/src/project';
import {createScriptCreationProfile} from '../../packages/script/src/creation';
import {anchorFor,outlineGuideId,type OutlineOwner} from '../../packages/script/src/outlineGuides';
const dbPath=process.env.SCRIPT_BROWSER_DB;
if(!dbPath?.startsWith('/tmp/'))throw new Error('浏览器验收必须使用 /tmp 隔离数据库');
const db=new Database(dbPath),repo=createScriptRepository(db);repo.ensureSchema();
const p=createScriptProject('节拍与故事线验收',createScriptCreationProfile('tv-series',3,20)),unit=p.units[0];
unit.scopeId='tail_story';unit.seasonId='tail_season';unit.title='第一集 · 旧信';
unit.summary='老周拆开旧信，发现记录上的时间被涂改。他决定去找证人，不再逃避旧案。';
unit.structureNodes=[{id:'tail_part_letter',title:'旧信带来疑问',purpose:'发现矛盾'},{id:'tail_part_decision',title:'决定核实证言',purpose:'开始行动'}];
unit.scenes[0].title='值班室拆信';unit.scenes[0].location='值班室';unit.scenes[0].timeOfDay='夜';unit.scenes[0].purpose='老周对照旧信和记录。';unit.scenes[0].structureNodeId='tail_part_letter';unit.scenes[0].blocks[0].text='老周把旧信摊在记录簿上。';
unit.scenes.push({...newScene('去找证人'),structureNodeId:'tail_part_decision',purpose:'老周走出值班室，联系证人。'});
const second=newUnit('第二集 · 证人',unit.targetDurationMs,'tail_story');second.seasonId='tail_season';
const other=newUnit('第三集 · 海港',unit.targetDurationMs,'tail_other_story');other.seasonId='tail_season';
p.units.push(second,other);p.seasons=[{id:'tail_season',title:'第一季',arc:'父女在旧案证言中找到缺口，最终公开记录。'}];
p.brief.outline='调查员走访三座城市，核实多年前的事故记录。';p.storyOutlines=[{scopeId:'tail_story',outline:'父女从旧信开始追查，在证人证词中找回相互信任。'}];
p.storylines=[{id:'tail_global_line',scopeId:p.id,lane:'A',title:'旧案调查',premise:'记录为何被涂改',resolution:'公开事故真相'},{id:'tail_local_line',scopeId:'tail_story',lane:'B',title:'父女关系',premise:'她是否还信任父亲',resolution:'相互理解'},{id:'tail_season_line',scopeId:'tail_season',lane:'A',title:'本季证言',premise:'证人隐藏了什么',resolution:'核实口供'},{id:'tail_foreign_line',scopeId:'tail_other_story',lane:'C',title:'海港货物秘密',premise:'其他故事的独有问题',resolution:'找到货物'}];
unit.scenes[0].storylineIds=['tail_local_line'];
const owner:OutlineOwner={kind:'unit',id:unit.id},split=unit.summary.indexOf('他决定');
p.outlineGuides=[{id:outlineGuideId(owner),owner,nodeLinks:[{unitId:unit.id,nodeId:'tail_part_letter',anchor:anchorFor(unit.summary,0,split)},{unitId:unit.id,nodeId:'tail_part_decision',anchor:anchorFor(unit.summary,split,unit.summary.length)}],beats:[{id:'tail_beat_doubt',title:'发现时间矛盾',change:'从以为旧案结束到产生怀疑',anchors:[anchorFor(unit.summary,0,split)],unitIds:[unit.id],sceneRefs:[{unitId:unit.id,sceneId:unit.scenes[0].id}],storylineIds:['tail_global_line']},{id:'tail_beat_decision',title:'决定找证人',change:'从逃避到主动核实',anchors:[anchorFor(unit.summary,split,unit.summary.length)],unitIds:[unit.id],sceneRefs:[{unitId:unit.id,sceneId:unit.scenes[1].id}],storylineIds:['tail_local_line']}]}];
const seasonOwner:OutlineOwner={kind:'season',id:'tail_season'};
p.outlineGuides.push({id:outlineGuideId(seasonOwner),owner:seasonOwner,nodeLinks:[],beats:[{id:'tail_season_beat',title:'公开记录',change:'从掩盖到承担责任',anchors:[anchorFor(p.seasons[0].arc,0,p.seasons[0].arc.length)],unitIds:[unit.id],sceneRefs:[],storylineIds:['tail_season_line']}]});
const saved=repo.saveProject(p,0),result={projectId:saved.id,unitId:unit.id,sceneId:unit.scenes[0].id,secondSceneId:unit.scenes[1].id,otherUnitId:other.id};
writeFileSync('/tmp/script-beat-storyline-fixture.json',JSON.stringify(result));console.log(JSON.stringify(result));db.close();
